import { Input } from './input';
import { Scene } from './scene';

export class Game {
  scene: Scene;
  input: Input;
  playerPosition: { x: number, y: number };
  playerHidden: boolean;
  gameState: any;

  constructor(scene: Scene, input: Input) {
    this.scene = scene;
    this.input = input;
    this.playerPosition = { x: 0, y: 0 };
    this.playerHidden = false;
    this.gameState = {};
  }

  update(deltaTime: number) {
    this.handleInput();
    // Additional game logic can be added here
  }

  handleInput() {
    if (this.input.isKeyPressed('left')) {
      this.movePlayer('left', 1);
    }
    if (this.input.isKeyPressed('right')) {
      this.movePlayer('right', 1);
    }
    if (this.input.isKeyPressed('up')) {
      this.movePlayer('up', 1);
    }
    if (this.input.isKeyPressed('down')) {
      this.movePlayer('down', 1);
    }
    if (this.input.isKeyPressed('h')) {
      this.playerHidden = !this.playerHidden;
    }
  }

  render() {
    this.scene.clear();
    this.scene.drawPlayer(this.playerPosition, this.playerHidden);
    // Additional rendering logic can be added here
  }

  isPlayerHidden() {
    return this.playerHidden;
  }

  movePlayer(direction: string, distance: number) {
    switch (direction) {
      case 'left':
        this.playerPosition.x -= distance;
        break;
      case 'right':
        this.playerPosition.x += distance;
        break;
      case 'up':
        this.playerPosition.y -= distance;
        break;
      case 'down':
        this.playerPosition.y += distance;
        break;
      default:
        break;
    }
  }
}

export function GameLoop(game: Game, targetFPS: number = 60) {
  const frameDuration = 1000 / targetFPS;
  let lastFrameTime = performance.now();
  let accumulator = 0;

  function step(currentTime: number) {
    const delta = currentTime - lastFrameTime;
    lastFrameTime = currentTime;
    accumulator += delta;

    while (accumulator >= frameDuration) {
      game.update(frameDuration / 1000);
      accumulator -= frameDuration;
    }

    game.render();
    requestAnimationFrame(step);
  }

  requestAnimationFrame(step);
}

