export class Cheese {
  position: { x: number, y: number, z: number };
  velocity: { x: number, y: number, z: number };
  acceleration: { x: number, y: number, z: number };
  score: number;

  constructor() {
    this.position = { x: 0, y: 0, z: 0 };
    this.velocity = { x: 0, y: 0, z: 0 };
    this.acceleration = { x: 0, y: 0, z: 0 };
    this.score = 0;
  }

  update(deltaTime: number): void {
    this.velocity.x += this.acceleration.x * deltaTime;
    this.velocity.y += this.acceleration.y * deltaTime;
    this.velocity.z += this.acceleration.z * deltaTime;
    this.position.x += this.velocity.x * deltaTime;
    this.position.y += this.velocity.y * deltaTime;
    this.position.z += this.velocity.z * deltaTime;
  }

  move(direction: { x: number, y: number, z: number }): void {
    this.acceleration.x = direction.x;
    this.acceleration.y = direction.y;
    this.acceleration.z = direction.z;
  }

  collectItem(item: { type: string, value: number }): void {
    if (item.type === 'cheese') {
      this.score += item.value;
    }
  }

  collideWithEnemy(enemy: { type: string, damage: number }): void {
    if (enemy.type === 'enemy') {
      this.score -= enemy.damage;
    }
  }
}

