import * as THREE from 'three';

class Tile {
  constructor(position) {
    this.position = position;
    this.piece = null;
    this.isHighlighted = false;
    this.mesh = createTileMesh(position);
  }

  setPiece(piece) {
    this.piece = piece;
    this.mesh.add(createPieceMesh(piece));
  }

  removePiece() {
    this.piece = null;
    this.mesh.remove(this.mesh.children[1]); // Assuming the piece mesh is the second child
  }

  highlight() {
    this.isHighlighted = true;
    this.mesh.material.color.set(0x00ff00);
  }

  unhighlight() {
    this.isHighlighted = false;
    this.mesh.material.color.set(0xffffff);
  }

  render() {
    return this.mesh;
  }
}

function createTileMesh(position) {
  const geometry = new THREE.BoxGeometry(1, 0.1, 1);
  const material = new THREE.MeshBasicMaterial({ color: 0xffffff });
  const mesh = new THREE.Mesh(geometry, material);
  mesh.position.set(position.x, 0.05, position.z);
  return mesh;
}

function createPieceMesh(piece) {
  const geometry = new THREE.BoxGeometry(0.8, 0.8, 0.8);
  const material = new THREE.MeshBasicMaterial({ color: piece.color === 'white' ? 0xffffff : 0x000000 });
  const mesh = new THREE.Mesh(geometry, material);
  return mesh;
}

