import { Ledger } from './ledger';
import { Storage } from './storage';

export function startCli() {
    const ledger = new Ledger(new Storage());
    console.log('Welcome to the Banking Ledger CLI. Type "help" for a list of commands.');

    while (true) {
        const input = prompt('> ');
        if (!input) continue;

        const [command, ...args] = input.split(' ');

        switch (command) {
            case 'deposit':
                handleDeposit(ledger, args);
                break;
            case 'withdraw':
                handleWithdraw(ledger, args);
                break;
            case 'balance':
                handleBalance(ledger, args);
                break;
            case 'history':
                handleHistory(ledger, args);
                break;
            case 'help':
                displayHelp();
                break;
            case 'exit':
                console.log('Exiting CLI. Goodbye!');
                return;
            default:
                console.log('Unknown command. Type "help" for a list of commands.');
        }
    }
}

function handleDeposit(ledger: Ledger, args: string[]) {
    if (args.length !== 2) {
        console.log('Usage: deposit <account> <amount>');
        return;
    }
    const account = args[0];
    const amount = parseFloat(args[1]);
    if (isNaN(amount)) {
        console.log('Invalid amount. Please enter a number.');
        return;
    }
    ledger.deposit(account, amount);
    console.log(`Deposited ${amount} to account ${account}.`);
}

function handleWithdraw(ledger: Ledger, args: string[]) {
    if (args.length !== 2) {
        console.log('Usage: withdraw <account> <amount>');
        return;
    }
    const account = args[0];
    const amount = parseFloat(args[1]);
    if (isNaN(amount)) {
        console.log('Invalid amount. Please enter a number.');
        return;
    }
    ledger.withdraw(account, amount);
    console.log(`Withdrew ${amount} from account ${account}.`);
}

function handleBalance(ledger: Ledger, args: string[]) {
    if (args.length !== 1) {
        console.log('Usage: balance <account>');
        return;
    }
    const account = args[0];
    const balance = ledger.getBalance(account);
    console.log(`Balance of account ${account}: ${balance}`);
}

function handleHistory(ledger: Ledger, args: string[]) {
    if (args.length !== 1) {
        console.log('Usage: history <account>');
        return;
    }
    const account = args[0];
    const history = ledger.getTransactionHistory(account);
    console.log(`Transaction history of account ${account}:`);
    history.forEach((tx) => console.log(`${tx.type} ${tx.amount} at ${tx.timestamp}`));
}

function displayHelp() {
    console.log(`
        Available commands:
        deposit <account> <amount> - Deposit money into an account
        withdraw <account> <amount> - Withdraw money from an account
        balance <account> - Check the balance of an account
        history <account> - View the transaction history of an account
        help - Display this help message
        exit - Exit the CLI
    `);
}

import * as fs from 'fs';
import * as path from 'path';

const ACCOUNTS_FILE_PATH = path.join(__dirname, 'accounts.json');

export function loadAccounts(): Account[] {
  try {
    const data = fs.readFileSync(ACCOUNTS_FILE_PATH, 'utf-8');
    return JSON.parse(data);
  } catch (error) {
    if (error.code === 'ENOENT') {
      return [];
    }
    throw new Error(`Failed to load accounts: ${error.message}`);
  }
}

export function saveAccounts(accounts: Account[]): void {
  try {
    const data = JSON.stringify(accounts, null, 2);
    fs.writeFileSync(ACCOUNTS_FILE_PATH, data);
  } catch (error) {
    throw new Error(`Failed to save accounts: ${error.message}`);
  }
}

import { deposit, withdraw, getBalance, recordTransaction } from './ledger';
import { save, load } from './store';
import { addTransaction, getHistory } from './history';

export function run() {
  let balance = load() || 0;
  let history = getHistory();

  while (true) {
    const input = prompt('Enter command (deposit, withdraw, balance, history, exit): ');
    if (!input) continue;

    const [command, ...args] = input.split(' ');

    switch (command) {
      case 'deposit':
        if (args.length !== 1) {
          console.log('Usage: deposit <amount>');
          continue;
        }
        const amount = parseFloat(args[0]);
        if (isNaN(amount) || amount <= 0) {
          console.log('Invalid amount');
          continue;
        }
        balance = deposit(balance, amount);
        recordTransaction(`Deposited ${amount}`);
        save(balance);
        console.log(`Deposited ${amount}. New balance: ${balance}`);
        break;
      case 'withdraw':
        if (args.length !== 1) {
          console.log('Usage: withdraw <amount>');
          continue;
        }
        const withdrawAmount = parseFloat(args[0]);
        if (isNaN(withdrawAmount) || withdrawAmount <= 0) {
          console.log('Invalid amount');
          continue;
        }
        balance = withdraw(balance, withdrawAmount);
        recordTransaction(`Withdrew ${withdrawAmount}`);
        save(balance);
        console.log(`Withdrew ${withdrawAmount}. New balance: ${balance}`);
        break;
      case 'balance':
        console.log(`Current balance: ${balance}`);
        break;
      case 'history':
        console.log('Transaction history:');
        history.forEach((entry) => console.log(entry));
        break;
      case 'exit':
        console.log('Exiting...');
        return;
      default:
        console.log('Unknown command. Type "help" for a list of commands.');
        break;
    }
  }
}

