  saveState(state: LedgerState): void {
    this.history.push({ state, timestamp: new Date() });
  }

  revertToState(index: number): LedgerState | null {
    if (index < 0 || index >= this.history.length) {
      return null;
    }
    const { state } = this.history[index];
    // Assuming there's a way to update the ledger state
    // updateLedgerState(state);
    return state;
  }

  clearHistory(): void {
    this.history = [];
  }
}

export const historyManager = new HistoryManager();
export const revertToState = (index: number): LedgerState | null => historyManager.revertToState(index);

export class Account {
  id: string;
  balance: number;
  history: Transaction[];

  constructor(id: string) {
    this.id = id;
    this.balance = 0;
    this.history = [];
  }

  deposit(amount: number): void {
    this.balance += amount;
    this.history.push(new Transaction(amount, 'deposit'));
  }

  withdraw(amount: number): void {
    if (amount > this.balance) {
      throw new Error('Insufficient funds');
    }
    this.balance -= amount;
    this.history.push(new Transaction(amount, 'withdrawal'));
  }

  getBalance(): number {
    return this.balance;
  }

  getHistory(): Transaction[] {
    return this.history;
  }
}

export class Transaction {
  id: string;
  amount: number;
  type: 'deposit' | 'withdrawal';
  timestamp: Date;

  constructor(amount: number, type: 'deposit' | 'withdrawal') {
    this.id = Date.now().toString();
    this.amount = amount;
    this.type = type;
    this.timestamp = new Date();
  }
}

export class Ledger {
  accounts: Account[];

  constructor() {
    this.accounts = [];
  }

  createAccount(id: string): Account {
    const account = new Account(id);
    this.accounts.push(account);
    return account;
  }

  getAccount(id: string): Account | undefined {
    return this.accounts.find(a => a.id === id);
  }

  deposit(accountId: string, amount: number): void {
    const account = this.getAccount(accountId);
    if (!account) {
      throw new Error('Account not found');
    }
    account.deposit(amount);
  }

  withdraw(accountId: string, amount: number): void {
    const account = this.getAccount(accountId);
    if (!account) {
      throw new Error('Account not found');
    }
    account.withdraw(amount);
  }

  showBalance(accountId: string): number {
    const account = this.getAccount(accountId);
    if (!account) {
      throw new Error('Account not found');
    }
    return account.getBalance();
  }

  getHistory(accountId: string): Transaction[] {
    const account = this.getAccount(accountId);
    if (!account) {
      throw new Error('Account not found');
    }
    return account.getHistory();
  }
}

export function deposit(accountId: string, amount: number): void {
  const ledger = new Ledger();
  ledger.deposit(accountId, amount);
}

export function withdraw(accountId: string, amount: number): void {
  const ledger = new Ledger();
  ledger.withdraw(accountId, amount);
}

export function showBalance(accountId: string): number {
  const ledger = new Ledger();
  return ledger.showBalance(accountId);
}

export function getHistory(accountId: string): Transaction[] {
  const ledger = new Ledger();
  return ledger.getHistory(accountId);
}

export type BudgetItem = {
  id: string;
  description: string;
  amount: number;
  participants: string[];
};

let budgetItems: BudgetItem[] = [];

export function addBudgetItem(item: BudgetItem): void {
  budgetItems.push(item);
}

export function updateBudgetItem(id: string, updatedItem: BudgetItem): void {
  budgetItems = budgetItems.map(item => item.id === id ? updatedItem : item);
}

export function deleteBudgetItem(id: string): void {
  budgetItems = budgetItems.filter(item => item.id !== id);
}

export function getBudgetItems(): BudgetItem[] {
  return budgetItems;
}

export function splitExpense(description: string, amount: number, participants: string[]): BudgetItem {
  const item: BudgetItem = {
    id: Date.now().toString(),
    description,
    amount,
    participants,
  };
  addBudgetItem(item);
  return item;
}

export function calculateOwes(): Record<string, number> {
  const owes: Record<string, number> = {};
  budgetItems.forEach(item => {
    const perPerson = item.amount / item.participants.length;
    item.participants.forEach(participant => {
      owes[participant] = (owes[participant] || 0) + perPerson;
    });
  });
  return owes;
}

