import { Expense, Friend, Balance } from './types';

/**
 * Splits an expense among friends.
 * @param amount - The total amount of the expense.
 * @param friends - An array of friend names.
 * @returns An object indicating how much each friend owes.
 */
export function splitExpense(amount: number, friends: string[]): Record<string, number> {
  const splitAmount = amount / friends.length;
  const expenseSplit: Record<string, number> = {};

  friends.forEach(friend => {
    expenseSplit[friend] = splitAmount;
  });

  return expenseSplit;
}

/**
 * Calculates the net balance for each friend based on a list of expenses.
 * @param expenses - An array of expenses.
 * @returns An object indicating the net balance for each friend.
 */
export function calculateBalances(expenses: Expense[]): Balance {
  const balances: Balance = {};

  expenses.forEach(expense => {
    const splitAmount = expense.amount / expense.friends.length;

    expense.friends.forEach(friend => {
      if (!balances[friend]) {
        balances[friend] = 0;
      }
      balances[friend] -= splitAmount;
    });

    expense.payer = expense.payer || '';
    if (balances[expense.payer]) {
      balances[expense.payer] += expense.amount;
    } else {
      balances[expense.payer] = expense.amount;
    }
  });

  return balances;
}

export function parseExpense(input: string): { date: string, description: string, amount: number } {
  const parts = input.split(',');
  if (parts.length !== 3) {
    throw new Error('Invalid expense format');
  }
  return {
    date: parts[0].trim(),
    description: parts[1].trim(),
    amount: parseFloat(parts[2].trim())
  };
}

export function writeToFile(expenses: { date: string, description: string, amount: number }[], filePath: string): void {
  try {
    const data = JSON.stringify(expenses, null, 2);
    require('fs').writeFileSync(filePath, data);
  } catch (err) {
    console.error('Error writing to file:', err);
  }
}

