/**
 * Validates an email address.
 * @param email - The email address to validate.
 * @returns True if the email is valid, false otherwise.
 */
export function validateEmail(email: string): boolean {
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    return emailRegex.test(email);
}

/**
 * Validates a phone number.
 * @param phone - The phone number to validate.
 * @returns True if the phone number is valid, false otherwise.
 */
export function validatePhone(phone: string): boolean {
    const phoneRegex = /^\+?[1-9]\d{1,14}$/; // E.164 format
    return phoneRegex.test(phone);
}

import { organizeFiles } from './organizer';

export function parseArgs(args: string[]): { source: string, destination: string, dryRun: boolean } {
  let source = '';
  let destination = '';
  let dryRun = false;

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--source') {
      source = args[i + 1] || '';
      i++;
    } else if (args[i] === '--destination') {
      destination = args[i + 1] || '';
      i++;
    } else if (args[i] === '--dry-run') {
      dryRun = true;
    }
  }

  return { source, destination, dryRun };
}

export function printResults(results: { moved: number, errors: number, dryRun: boolean, files: string[] }) {
  console.log(`Moved ${results.moved} files.`);
  if (results.errors > 0) {
    console.log(`Encountered ${results.errors} errors.`);
  }
  if (results.dryRun) {
    console.log('Dry run preview:');
    results.files.forEach(file => console.log(file));
  }
}

import { organizeFiles, previewChanges } from './organizer';
import { parseArgs } from './cli';

export function run() {
  const args = parseArgs();
  if (!args.directory) {
    console.error('Directory path is required.');
    return;
  }

  try {
    if (args.dryRun) {
      console.log('Dry run preview:');
      previewChanges(args.directory);
    } else {
      organizeFiles(args.directory);
      console.log('Files organized successfully.');
    }
  } catch (error) {
    console.error('Error during file organization:', error);
  }
}

