import React, { useState } from 'react';
import { Note } from '../../src/models/note.ts';
import { addNote, updateNote } from '../../src/services/noteService.ts';

interface NoteFormProps {
  note?: Note;
  onSubmit: () => void;
}

export const NoteForm: React.FC<NoteFormProps> = ({ note, onSubmit }) => {
  const [title, setTitle] = useState(note ? note.title : '');
  const [content, setContent] = useState(note ? note.content : '');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState('');

  const handleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const { name, value } = e.target;
    if (name === 'title') setTitle(value);
    else setContent(value);
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSubmitting(true);
    setError('');
    try {
      if (note) {
        await updateNote({ ...note, title, content });
      } else {
        await addNote({ title, content });
      }
      onSubmit();
    } catch (err) {
      setError('An error occurred. Please try again.');
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <form onSubmit={handleSubmit}>
      <div>
        <label htmlFor="title">Title</label>
        <input type="text" id="title" name="title" value={title} onChange={handleChange} required />
      </div>
      <div>
        <label htmlFor="content">Content</label>
        <textarea id="content" name="content" value={content} onChange={handleChange} required />
      </div>
      {error && <p style={{ color: 'red' }}>{error}</p>}
      <button type="submit" disabled={isSubmitting}>Save</button>
    </form>
  );
};

