    } catch (err) {
      setError('Failed to add note');
    }
  };

  const deleteNote = async (id: string) => {
    try {
      await axios.delete(`/api/notes/${id}`);
      setNotes(notes.filter(note => note.id !== id));
    } catch (err) {
      setError('Failed to delete note');
    }
  };

  return (
    <div>
      {loading && <p>Loading notes...</p>}
