import { Note } from './types';
import { DatabaseConnection } from './db';

class NoteRepository {
  private db: DatabaseConnection;

  constructor(db: DatabaseConnection) {
    this.db = db;
  }

  async getAllNotes(): Promise<Note[]> {
    return this.db.query('SELECT * FROM notes');
  }

  async getNoteById(id: string): Promise<Note | null> {
    const result = await this.db.query('SELECT * FROM notes WHERE id = ?', [id]);
    return result.length > 0 ? result[0] : null;
  }

  async createNote(note: Note): Promise<Note> {
    await this.db.query('INSERT INTO notes (id, title, content) VALUES (?, ?, ?)', [note.id, note.title, note.content]);
    return note;
  }

  async updateNote(id: string, note: Note): Promise<Note | null> {
    const result = await this.db.query('UPDATE notes SET title = ?, content = ? WHERE id = ?', [note.title, note.content, id]);
    return result.affectedRows > 0 ? note : null;
  }

  async deleteNote(id: string): Promise<boolean> {
    const result = await this.db.query('DELETE FROM notes WHERE id = ?', [id]);
    return result.affectedRows > 0;
  }
}

class NoteService {
  private repository: NoteRepository;

  constructor(repository: NoteRepository) {
    this.repository = repository;
  }

  async getAllNotes(): Promise<Note[]> {
    return this.repository.getAllNotes();
  }

  async getNoteById(id: string): Promise<Note | null> {
    return this.repository.getNoteById(id);
  }

  async createNote(note: Note): Promise<Note> {
    return this.repository.createNote(note);
  }

  async updateNote(id: string, note: Note): Promise<Note | null> {
    return this.repository.updateNote(id, note);
  }

  async deleteNote(id: string): Promise<boolean> {
    return this.repository.deleteNote(id);
  }
}

