import { ObjectId } from 'mongodb';
import { db } from '../database';

export interface Note {
  _id?: ObjectId;
  title: string;
  content: string;
  createdAt: Date;
}

export const addNote = async (note: Omit<Note, '_id'>): Promise<Note> => {
  const result = await db.collection('notes').insertOne(note);
  return { ...note, _id: result.insertedId };
};

export const getAllNotes = async (): Promise<Note[]> => {
  return await db.collection('notes').find().toArray();
};

export const getNoteById = async (id: string): Promise<Note | null> => {
  return await db.collection('notes').findOne({ _id: new ObjectId(id) });
};

export const updateNote = async (id: string, updatedNote: Omit<Note, '_id'>): Promise<Note | null> => {
  const result = await db.collection('notes').updateOne(
    { _id: new ObjectId(id) },
    { $set: updatedNote }
  );
  return result.matchedCount > 0 ? { _id: new ObjectId(id), ...updatedNote } : null;
};

export const deleteNote = async (id: string): Promise<boolean> => {
  const result = await db.collection('notes').deleteOne({ _id: new ObjectId(id) });
  return result.deletedCount > 0;
};

