// Imports
import { NoteStorage } from './storage';
import { Note } from './types';

// Note Interface
export interface Note {
  id: string;
  title: string;
  content: string;
  createdAt: Date;
  updatedAt: Date;
}

// NotesService Class
class NotesService {
  private storage: NoteStorage;

  constructor(storage: NoteStorage) {
    this.storage = storage;
  }

  async createNote(note: Omit<Note, 'id' | 'createdAt' | 'updatedAt'>): Promise<Note> {
    const newNote: Note = {
      ...note,
      id: Date.now().toString(),
      createdAt: new Date(),
      updatedAt: new Date(),
    };
    await this.storage.saveNote(newNote);
    return newNote;
  }

  async getNotes(): Promise<Note[]> {
    return this.storage.getNotes();
  }

  async updateNote(id: string, update: Partial<Omit<Note, 'id' | 'createdAt'>>): Promise<Note | null> {
    const note = await this.storage.getNoteById(id);
    if (!note) return null;

    const updatedNote: Note = {
      ...note,
      ...update,
      updatedAt: new Date(),
    };
    await this.storage.updateNote(updatedNote);
    return updatedNote;
  }

  async deleteNote(id: string): Promise<boolean> {
    return this.storage.deleteNote(id);
  }
}

// CRUD Functions
export const createNote = async (note: Omit<Note, 'id' | 'createdAt' | 'updatedAt'>): Promise<Note> => {
  const storage = new NoteStorage();
  const notesService = new NotesService(storage);
  return await notesService.createNote(note);
};

export const getNotes = async (): Promise<Note[]> => {
  const storage = new NoteStorage();
  const notesService = new NotesService(storage);
  return await notesService.getNotes();
};

export const updateNote = async (id: string, update: Partial<Omit<Note, 'id' | 'createdAt'>>): Promise<Note | null> => {
  const storage = new NoteStorage();
  const notesService = new NotesService(storage);
  return await notesService.updateNote(id, update);
};

export const deleteNote = async (id: string): Promise<boolean> => {
  const storage = new NoteStorage();
  const notesService = new NotesService(storage);
  return await notesService.deleteNote(id);
};

