import { Habit, Streak } from './types';
import { StorageService } from './storageService';

class HabitService {
  private habits: Habit[] = [];
  private storageService: StorageService;

  constructor(storageService: StorageService) {
    this.storageService = storageService;
    this.loadHabits();
  }

  private loadHabits() {
    const storedHabits = this.storageService.getHabits();
    if (storedHabits) {
      this.habits = storedHabits;
    }
  }

  private saveHabits() {
    this.storageService.saveHabits(this.habits);
  }

  addHabit(habit: Habit) {
    this.habits.push(habit);
    this.saveHabits();
  }

  markDone(habitId: string, date: Date) {
    const habit = this.habits.find(h => h.id === habitId);
    if (habit) {
      habit.doneDates.push(date);
      this.saveHabits();
    }
  }

  getStreaks(): Streak[] {
    const streaks: Streak[] = [];
    for (const habit of this.habits) {
      let currentStreak = 0;
      let maxStreak = 0;
      for (let i = 0; i < habit.doneDates.length; i++) {
        if (i > 0 && habit.doneDates[i].getTime() - habit.doneDates[i - 1].getTime() !== 86400000) {
          currentStreak = 0;
        }
        currentStreak++;
        maxStreak = Math.max(maxStreak, currentStreak);
      }
      streaks.push({ habitId: habit.id, maxStreak });
    }
    return streaks;
  }
}

