import { ParsedLog, ModuleReport } from './types';

// Constants
const TOP_MODULES_COUNT = 5;

// Function to report top modules by error count
export function reportTopModules(parsedLogs: ParsedLog[]): ModuleReport[] {
  // Filter logs to include only errors
  const errorLogs = parsedLogs.filter(log => log.level === 'error');

  // Group error logs by module and count errors
  const moduleErrorCounts: { [module: string]: number } = {};
  errorLogs.forEach(log => {
    if (moduleErrorCounts[log.module]) {
      moduleErrorCounts[log.module]++;
    } else {
      moduleErrorCounts[log.module] = 1;
    }
  });

  // Convert to array and sort by error count in descending order
  const sortedModules = Object.entries(moduleErrorCounts)
    .map(([module, count]) => ({ module, count }))
    .sort((a, b) => b.count - a.count);

  // Return the top N modules
  return sortedModules.slice(0, TOP_MODULES_COUNT);
}

