// Function to scale servings
export function scaleServings(recipeId: string, newServings: number): RecipeItem | null {
  const recipe = recipes.find(r => r.id === recipeId);
  if (!recipe) return null;

  const scaleFactor = newServings / recipe.servings;
  const scaledIngredients = recipe.ingredients.map(i => ({
    ...i,
    quantity: i.quantity * scaleFactor,
  }));

  const scaledRecipe = {
    ...recipe,
    servings: newServings,
    ingredients: scaledIngredients,
  };

  // Update the recipe in the list
  const index = recipes.findIndex(r => r.id === recipeId);
  if (index !== -1) {
    recipes[index] = scaledRecipe;
  }

  // Optionally, save to storage
  saveRecipesToStorage();

  return scaledRecipe;
}

