    if (this.currentRoom.removeItem(item)) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }

  dropItem(item: Item): boolean {
    if (this.inventory.removeItem(item)) {
      this.currentRoom.addItem(item);
      return true;
    }
    return false;
  }

  getInventory(): string[] {
    return this.inventory.listItems();
  }
}

