  return text.split(/\s+/).filter(word => word.length > 0).length;
}

export function countChars(text: string): number {
  return text.length;
}

export function countSentences(text: string): number {
  return text.split(/(?<=[.!?])\s+/).filter(sentence => sentence.length > 0).length;
}

export function getMostFrequentWords(text: string, limit = 5): string[] {
  const words = text.split(/\s+/).filter(word => word.length > 0);
  const wordCount: { [word: string]: number } = {};
  for (const word of words) {
    wordCount[word] = (wordCount[word] || 0) + 1;
  }
  const sortedWords = Object.entries(wordCount).sort((a, b) => b[1] - a[1]);
  return sortedWords.slice(0, limit).map(entry => entry[0]);
}

