export class Game {
  private board: Board;
  private players: Player[];
  private currentPlayerIndex: number;

  constructor() {
    this.board = new Board();
    this.players = [new Player('X'), new Player('O')];
    this.currentPlayerIndex = 0;
  }

  getCurrentPlayer(): Player {
    return this.players[this.currentPlayerIndex];
  }

  makeMove(row: number, col: number): boolean {
    if (!this.board.isCellEmpty(row, col)) {
      return false;
    }
    this.board.setCellValue(row, col, this.getCurrentPlayer().getMark());
    if (this.checkWin()) {
      console.log(`${this.getCurrentPlayer().getMark()} wins!`);
      return true;
    }
    if (this.checkTie()) {
      console.log('It\'s a tie!');
      return true;
    }
    this.switchPlayer();
    return false;
  }

  checkWin(): boolean {
    const board = this.board;
    const lines = [
      [board.getCellValue(0, 0), board.getCellValue(0, 1), board.getCellValue(0, 2)],
      [board.getCellValue(1, 0), board.getCellValue(1, 1), board.getCellValue(1, 2)],
      [board.getCellValue(2, 0), board.getCellValue(2, 1), board.getCellValue(2, 2)],
      [board.getCellValue(0, 0), board.getCellValue(1, 0), board.getCellValue(2, 0)],
      [board.getCellValue(0, 1), board.getCellValue(1, 1), board.getCellValue(2, 1)],
      [board.getCellValue(0, 2), board.getCellValue(1, 2), board.getCellValue(2, 2)],
      [board.getCellValue(0, 0), board.getCellValue(1, 1), board.getCellValue(2, 2)],
      [board.getCellValue(0, 2), board.getCellValue(1, 1), board.getCellValue(2, 0)]
    ];
    for (const line of lines) {
      if (line[0] && line[0] === line[1] && line[1] === line[2]) {
        return true;
      }
    }
    return false;
  }

  checkTie(): boolean {
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        if (this.board.isCellEmpty(row, col)) {
          return false;
        }
      }
    }
    return true;
  }

  switchPlayer(): void {
    this.currentPlayerIndex = 1 - this.currentPlayerIndex;
  }

  resetGame(): void {
    this.board.reset();
    this.currentPlayerIndex = 0;
  }
}

