export enum GameState {
  Playing = 'Playing',
  Won = 'Won',
  Tied = 'Tied',
}

export class Board {
  private cells: ('X' | 'O' | null)[][];
  private size: number;

  constructor(size: number = 3) {
    this.size = size;
    this.cells = Array.from({ length: size }, () => Array(size).fill(null));
  }

  public getCell(row: number, col: number): 'X' | 'O' | null {
    return this.cells[row][col];
  }

  public setCell(row: number, col: number, value: 'X' | 'O' | null): void {
    this.cells[row][col] = value;
  }

  public isFull(): boolean {
    return this.cells.every(row => row.every(cell => cell !== null));
  }

  public getBoard(): ('X' | 'O' | null)[][] {
    return this.cells;
  }
}

export class GameLogic {
  private board: Board;
  private currentPlayer: 'X' | 'O' = 'X';
  private state: GameState = GameState.Playing;

  constructor(size: number = 3) {
    this.board = new Board(size);
  }

  public getCurrentPlayer(): 'X' | 'O' {
    return this.currentPlayer;
  }

  public getGameState(): GameState {
    return this.state;
  }

  public makeMove(row: number, col: number): boolean {
    if (this.state !== GameState.Playing || this.board.getCell(row, col) !== null) {
      return false;
    }

    this.board.setCell(row, col, this.currentPlayer);
    if (this.checkWin(row, col)) {
      this.state = GameState.Won;
    } else if (this.board.isFull()) {
      this.state = GameState.Tied;
    } else {
      this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
    }

    return true;
  }

  private checkWin(row: number, col: number): boolean {
    const size = this.board.getBoard().length;
    const player = this.board.getCell(row, col);

    // Check row
    for (let c = 0; c < size; c++) {
      if (this.board.getCell(row, c) !== player) {
        break;
      }
      if (c === size - 1) {
        return true;
      }
    }

    // Check column
    for (let r = 0; r < size; r++) {
      if (this.board.getCell(r, col) !== player) {
        break;
      }
      if (r === size - 1) {
        return true;
      }
    }

    // Check diagonal (top-left to bottom-right)
    if (row === col) {
      for (let i = 0; i < size; i++) {
        if (this.board.getCell(i, i) !== player) {
          break;
        }
        if (i === size - 1) {
          return true;
        }
      }
    }

    // Check anti-diagonal (top-right to bottom-left)
    if (row + col === size - 1) {
      for (let i = 0; i < size; i++) {
        if (this.board.getCell(i, size - 1 - i) !== player) {
          break;
        }
        if (i === size - 1) {
          return true;
        }
      }
    }

    return false;
  }
}

