// Types and Constants
const EMPTY = ' ';
const PLAYER_X = 'X';
const PLAYER_O = 'O';
const BOARD_SIZE = 3;

// Helper Functions
function isBoardFull(board: string[][]): boolean {
    for (let row = 0; row < BOARD_SIZE; row++) {
        for (let col = 0; col < BOARD_SIZE; col++) {
            if (board[row][col] === EMPTY) {
                return false;
            }
        }
    }
    return true;
}

function checkWinner(board: string[][]): string | null {
    const lines = [
        // Rows
        [board[0][0], board[0][1], board[0][2]],
        [board[1][0], board[1][1], board[1][2]],
        [board[2][0], board[2][1], board[2][2]],
        // Columns
        [board[0][0], board[1][0], board[2][0]],
        [board[0][1], board[1][1], board[2][1]],
        [board[0][2], board[1][2], board[2][2]],
        // Diagonals
        [board[0][0], board[1][1], board[2][2]],
        [board[0][2], board[1][1], board[2][0]]
    ];

    for (const line of lines) {
        if (line[0] !== EMPTY &&
            line[0] === line[1] &&
            line[1] === line[2]) {
            return line[0];
        }
    }
    return null;
}

// Main Functions
function getValidMoves(board: string[][]): { row: number, col: number }[] {
    const moves: { row: number, col: number }[] = [];
    for (let row = 0; row < BOARD_SIZE; row++) {
        for (let col = 0; col < BOARD_SIZE; col++) {
            if (board[row][col] === EMPTY) {
                moves.push({ row, col });
            }
        }
    }
    return moves;
}

function evaluateBoard(board: string[][]): number {
    const winner = checkWinner(board);
    if (winner === PLAYER_X) {
        return 1;
    } else if (winner === PLAYER_O) {
        return -1;
    } else {
        return 0;
    }
}

function minimax(board: string[][], depth: number, isMaximizing: boolean): number {
    const winner = checkWinner(board);
    if (winner === PLAYER_X) {
        return 1;
    } else if (winner === PLAYER_O) {
        return -1;
    } else if (isBoardFull(board)) {
        return 0;
    }

    if (isMaximizing) {
        let bestScore = -Infinity;
        for (const move of getValidMoves(board)) {
            board[move.row][move.col] = PLAYER_X;
            const score = minimax(board, depth + 1, false);
            board[move.row][move.col] = EMPTY;
            bestScore = Math.max(score, bestScore);
        }
        return bestScore;
    } else {
        let bestScore = Infinity;
        for (const move of getValidMoves(board)) {
            board[move.row][move.col] = PLAYER_O;
            const score = minimax(board, depth + 1, true);
            board[move.row][move.col] = EMPTY;
            bestScore = Math.min(score, bestScore);
        }
        return bestScore;
    }
}

