export class Game {
  private board: string[][];
  private currentPlayer: string;
  private winner: string | null;

  constructor() {
    this.initializeBoard();
    this.currentPlayer = 'X';
    this.winner = null;
  }

  private initializeBoard() {
    this.board = Array.from({ length: 3 }, () => Array(3).fill(null));
  }

  public makeMove(row: number, col: number) {
    if (this.board[row][col] === null) {
      this.board[row][col] = this.currentPlayer;
      if (this.checkWin()) {
        this.winner = this.currentPlayer;
      } else if (this.checkDraw()) {
        this.winner = 'Draw';
      } else {
        this.switchPlayer();
      }
    }
  }

  private checkWin() {
    const lines = [
      // Rows
      [this.board[0][0], this.board[0][1], this.board[0][2]],
      [this.board[1][0], this.board[1][1], this.board[1][2]],
      [this.board[2][0], this.board[2][1], this.board[2][2]],
      // Columns
      [this.board[0][0], this.board[1][0], this.board[2][0]],
      [this.board[0][1], this.board[1][1], this.board[2][1]],
      [this.board[0][2], this.board[1][2], this.board[2][2]],
      // Diagonals
      [this.board[0][0], this.board[1][1], this.board[2][2]],
      [this.board[0][2], this.board[1][1], this.board[2][0]]
    ];
    for (const line of lines) {
      if (line[0] && line[0] === line[1] && line[0] === line[2]) {
        return true;
      }
    }
    return false;
  }

  private checkDraw() {
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        if (this.board[row][col] === null) {
          return false;
        }
      }
    }
    return true;
  }

  private switchPlayer() {
    this.currentPlayer = this.currentPlayer === 'X' ? 'O' : 'X';
  }

  public getBoard() {
    return this.board;
  }

  public getCurrentPlayer() {
    return this.currentPlayer;
  }

  public getWinner() {
    return this.winner;
  }
}

export class MinMaxComputer {
  private game: Game;

  constructor(game: Game) {
    this.game = game;
  }

  public getBestMove() {
    let bestMove = { row: -1, col: -1 };
    let bestScore = -Infinity;
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        if (this.game.getBoard()[row][col] === null) {
          this.game.makeMove(row, col);
          const score = this.minimax(false);
          this.game.makeMove(row, col); // Undo the move
          if (score > bestScore) {
            bestScore = score;
            bestMove = { row, col };
          }
        }
      }
    }
    return bestMove;
  }

  private minimax(isMaximizing: boolean) {
    const winner = this.game.getWinner();
    if (winner === 'X') return 1;
    if (winner === 'O') return -1;
    if (winner === 'Draw') return 0;

    if (isMaximizing) {
      let bestScore = -Infinity;
      for (let row = 0; row < 3; row++) {
        for (let col = 0; col < 3; col++) {
          if (this.game.getBoard()[row][col] === null) {
            this.game.makeMove(row, col);
            bestScore = Math.max(bestScore, this.minimax(false));
            this.game.makeMove(row, col); // Undo the move
          }
        }
      }
      return bestScore;
    } else {
      let bestScore = Infinity;
      for (let row = 0; row < 3; row++) {
        for (let col = 0; col < 3; col++) {
          if (this.game.getBoard()[row][col] === null) {
            this.game.makeMove(row, col);
            bestScore = Math.min(bestScore, this.minimax(true));
            this.game.makeMove(row, col); // Undo the move
          }
        }
      }
      return bestScore;
    }
  }
}

// Define the game board type
type Board = ('X' | 'O' | null)[][];

// Define the game state type
interface GameState {
  board: Board;
  currentPlayer: 'X' | 'O';
}

// Check if the game is over
function isGameOver(state: GameState): boolean {
  const lines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];
  for (const line of lines) {
    const [a, b, c] = line;
    if (state.board[a] && state.board[a] === state.board[b] && state.board[a] === state.board[c]) {
      return true;
    }
  }
  return !state.board.some(cell => cell === null);
}

// Determine the winner of the game
function getWinner(state: GameState): 'X' | 'O' | null {
  const lines = [
    [0, 1, 2], [3, 4, 5], [6, 7, 8],
    [0, 3, 6], [1, 4, 7], [2, 5, 8],
    [0, 4, 8], [2, 4, 6]
  ];
  for (const line of lines) {
    const [a, b, c] = line;
    if (state.board[a] && state.board[a] === state.board[b] && state.board[a] === state.board[c]) {
      return state.board[a];
    }
  }
  return null;
}

// Get all available moves on the board
function getAvailableMoves(state: GameState): number[] {
  return state.board.flatMap((cell, index) => cell === null ? index : []);
}

// Minimax algorithm implementation
function minimax(state: GameState, depth: number, isMaximizing: boolean): number {
  if (isGameOver(state)) {
    const winner = getWinner(state);
    if (winner === 'X') return 1;
    if (winner === 'O') return -1;
    return 0;
  }

  const availableMoves = getAvailableMoves(state);
  if (isMaximizing) {
    let bestScore = -Infinity;
    for (const move of availableMoves) {
      const newBoard = [...state.board];
      newBoard[move] = 'X';
      const score = minimax({ board: newBoard, currentPlayer: 'O' }, depth + 1, false);
      bestScore = Math.max(bestScore, score);
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (const move of availableMoves) {
      const newBoard = [...state.board];
      newBoard[move] = 'O';
      const score = minimax({ board: newBoard, currentPlayer: 'X' }, depth + 1, true);
      bestScore = Math.min(bestScore, score);
    }
    return bestScore;
  }
}

// Function to handle game state transitions
export function play(state: GameState, move: number): GameState {
  if (state.board[move] !== null || isGameOver(state)) {
    return state;
  }
  const newBoard = [...state.board];
  newBoard[move] = state.currentPlayer;
  const winner = getWinner({ board: newBoard, currentPlayer: state.currentPlayer });
  return { board: newBoard, currentPlayer: winner ? state.currentPlayer : state.currentPlayer === 'X' ? 'O' : 'X' };
}

