export enum Player {
  X = 'X',
  O = 'O',
  EMPTY = ' '
}

export class TicTacToe {
  private board: Player[][];
  private currentPlayer: Player;

  constructor() {
    this.board = Array.from({ length: 3 }, () => Array(3).fill(Player.EMPTY));
    this.currentPlayer = Player.X;
  }

  makeMove(row: number, col: number): boolean {
    if (this.board[row][col] === Player.EMPTY) {
      this.board[row][col] = this.currentPlayer;
      this.currentPlayer = this.currentPlayer === Player.X ? Player.O : Player.X;
      return true;
    }
    return false;
  }

  isGameOver(): boolean {
    return this.getWinner() !== Player.EMPTY || this.getAvailableMoves().length === 0;
  }

  getWinner(): Player {
    const lines = [
      // Rows
      [this.board[0][0], this.board[0][1], this.board[0][2]],
      [this.board[1][0], this.board[1][1], this.board[1][2]],
      [this.board[2][0], this.board[2][1], this.board[2][2]],
      // Columns
      [this.board[0][0], this.board[1][0], this.board[2][0]],
      [this.board[0][1], this.board[1][1], this.board[2][1]],
      [this.board[0][2], this.board[1][2], this.board[2][2]],
      // Diagonals
      [this.board[0][0], this.board[1][1], this.board[2][2]],
      [this.board[0][2], this.board[1][1], this.board[2][0]]
    ];

    for (const line of lines) {
      if (line[0] !== Player.EMPTY && line[0] === line[1] && line[1] === line[2]) {
        return line[0];
      }
    }

    return Player.EMPTY;
  }

  getAvailableMoves(): [number, number][] {
    const moves: [number, number][] = [];
    for (let row = 0; row < 3; row++) {
      for (let col = 0; col < 3; col++) {
        if (this.board[row][col] === Player.EMPTY) {
          moves.push([row, col]);
        }
      }
    }
    return moves;
  }
}

export function minimax(game: TicTacToe, depth: number, isMaximizing: boolean): number {
  if (game.isGameOver()) {
    const winner = game.getWinner();
    if (winner === Player.X) {
      return 10 - depth;
    } else if (winner === Player.O) {
      return depth - 10;
    } else {
      return 0;
    }
  }

  const moves = game.getAvailableMoves();
  if (isMaximizing) {
    let bestScore = -Infinity;
    for (const move of moves) {
      game.makeMove(move[0], move[1]);
      const score = minimax(game, depth + 1, false);
      game.makeMove(move[0], move[1]); // Undo the move
      bestScore = Math.max(bestScore, score);
    }
    return bestScore;
  } else {
    let bestScore = Infinity;
    for (const move of moves) {
      game.makeMove(move[0], move[1]);
      const score = minimax(game, depth + 1, true);
      game.makeMove(move[0], move[1]); // Undo the move
      bestScore = Math.min(bestScore, score);
    }
    return bestScore;
  }
}

