async function connectToDatabase() {
  const client = new MongoClient(uri, { useNewUrlParser: true, useUnifiedTopology: true });
  await client.connect();
  console.log('Connected to the database');
  db = client.db(dbName);
}

// Save URL mapping
async function saveUrlMapping(shortCode, longUrl) {
  if (!db) {
    throw new Error('Database connection not established');
  }
  const collection = db.collection('mappings');
  await collection.updateOne({ shortCode }, { $set: { longUrl } }, { upsert: true });
}

// Get URL mapping
async function getUrlMapping(shortCode) {
  if (!db) {
    throw new Error('Database connection not established');
  }
  const collection = db.collection('mappings');
  const result = await collection.findOne({ shortCode });
  return result ? result.longUrl : null;
}

// Connect to the database when the module is loaded
connectToDatabase();

module.exports = {
  saveUrlMapping,
  getUrlMapping,
};

