const POLL_STORAGE_KEY = 'voting-polls';

export function savePoll(poll: Poll): void {
  const polls = loadPolls();
  polls.push(poll);
  localStorage.setItem(POLL_STORAGE_KEY, JSON.stringify(polls));
}

export function loadPolls(): Poll[] {
  const pollsJson = localStorage.getItem(POLL_STORAGE_KEY);
  return pollsJson ? JSON.parse(pollsJson) : [];
}

