// src/storage.ts

import * as fs from 'fs';
import * as path from 'path';

// Define the file path for storing events
const EVENTS_FILE_PATH = path.join(__dirname, 'events.json');

// Define the type for an event
type Event = {
  id: string;
  name: string;
  date: Date;
};

// Function to load events from storage
export function loadEvents(): Event[] {
  try {
    const data = fs.readFileSync(EVENTS_FILE_PATH, 'utf-8');
    return JSON.parse(data) as Event[];
  } catch (error) {
    if (error.code === 'ENOENT') {
      // If the file does not exist, return an empty array
      return [];
    }
    throw new Error(`Failed to load events: ${error.message}`);
  }
}

// Function to save events to storage
export function saveEvents(events: Event[]): void {
  try {
    const data = JSON.stringify(events, null, 2);
    fs.writeFileSync(EVENTS_FILE_PATH, data, 'utf-8');
  } catch (error) {
    throw new Error(`Failed to save events: ${error.message}`);
  }
}

